using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using MP1SkinStudio.Live;

namespace MP1SkinStudio
{
    public static partial class SelfTests
    {
        static void RunFontDefinitionTests(string root)
        {
            string folder=Path.Combine(root,"font-definitions");Directory.CreateDirectory(folder);
            Write(folder,"references.xml","<controls><control><type>label</type><font>Body</font></control></controls>");
            Write(folder,"fonts.xml","<fonts><!-- keep font comment --><font custom='keep'><name>Body</name><filename>Arial</filename><height>12</height><unknown>preserve</unknown></font><font><name>Other</name><filename>Arial</filename><height>18</height></font><alias><name>Alias</name><fontname>Body</fontname></alias></fonts>");
            Write(folder,"main.xml","<window><id>0</id><controls><control><type>label</type><id>1</id><label>One</label></control><control><type>label</type><id>2</id><font>Alias</font><label>Two</label></control></controls></window>");
            Func<SkinProject> open=()=>{var p=new SkinProject(folder);p.OpenPage("main.xml");return p;};
            Test("Font descriptors preserve Unicode family, height and style",()=>{var original=new LiveFontDefinition{Family="Segoe UI",Height=24,Style=3};var parsed=LiveFontDefinition.Parse(original.ToWire());Check(parsed.Family==original.Family&&parsed.Height==24&&parsed.Style==3,"Font descriptor changed.");});
            Test("Font descriptors reject paths, oversized sizes and invalid flags",()=>{Reject(()=>new LiveFontDefinition{Family="../Arial",Height=18}.ToWire());Reject(()=>new LiveFontDefinition{Family="Arial",Height=0}.ToWire());Reject(()=>new LiveFontDefinition{Family="Arial",Height=200,Style=99}.ToWire());Reject(()=>LiveFontDefinition.Parse(LiveFontDefinition.Prefix+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes("<!DOCTYPE font [<!ENTITY x SYSTEM 'file:///invalid'>]><font family='Arial' height='18' style='0'/>"))));});
            Test("Font definition edits preserve unknown XML and exact Undo",()=>{var p=open();string before=p.Source(p.Resolve("fonts.xml")).Text;p.SetFontDefinition("Body","Segoe UI",24,true,false);Check(p.FontSpecs["Alias"].Height==24&&p.FontSpecs["Body"].Family=="Segoe UI","Alias did not follow definition.");string xml=p.Source(p.Resolve("fonts.xml")).Text;Check(xml.Contains("keep font comment")&&xml.Contains("custom='keep'")&&xml.Contains("<unknown>preserve</unknown>"),"Unknown font XML was lost.");p.UndoChange();Check(p.Source(p.Resolve("fonts.xml")).Text==before,"Font Undo changed source bytes.");});
            Test("Changed fonts preview every static alias use with private descriptors",()=>{var baseline=open();var p=open();var snapshot=LiveSnapshot(baseline);snapshot.DocumentElement.SetAttribute("fontDefinitions","private-v1");var binding=new LiveBinding(baseline,snapshot);p.SetFontDefinition("Body","Arial",24,false,true);var frame=binding.Frame(p,new Dictionary<string,Dictionary<string,string>>(),1);Check(frame.SelectNodes("/live/control/set[@key='font']").Count==2,"Shared alias uses were not updated.");foreach(System.Xml.XmlNode n in frame.SelectNodes("/live/control/set[@key='font']"))Check(LiveFontDefinition.Parse(n.InnerText).Height==24,"Definition lost height.");p.UndoChange();Check(binding.Frame(p,new Dictionary<string,Dictionary<string,string>>(),2).DocumentElement.ChildNodes.Count==0,"Font Undo retained a preview descriptor.");});
            Test("Old bridges reject font definition changes with update guidance",()=>{var baseline=open();var p=open();var binding=new LiveBinding(baseline,LiveSnapshot(baseline));p.SetFontDefinition("Body","Arial",22,false,false);Reject(()=>binding.Frame(p,new Dictionary<string,Dictionary<string,string>>(),1));});
            Test("Font alias edits preview retargeted definitions and reject cycles",()=>{var baseline=open();var p=open();var snapshot=LiveSnapshot(baseline);snapshot.DocumentElement.SetAttribute("fontDefinitions","private-v1");var binding=new LiveBinding(baseline,snapshot);p.SetFontAlias("Alias","Other");Check(p.FontSpecs["Alias"].Height==18,"Alias target unchanged.");Check(binding.Frame(p,new Dictionary<string,Dictionary<string,string>>(),1).SelectNodes("/live/control/set[@key='font']").Count==1,"Alias retarget changed unrelated fonts.");p.SetFontAlias("Chain","Alias");int history=p.Undo.Count;Reject(()=>p.SetFontAlias("Alias","Chain"));Check(p.Undo.Count==history,"Rejected alias cycle changed history.");});
            Test("New font definitions survive project save and preserve original files",()=>{var p=open();string disk=File.ReadAllText(p.Resolve("fonts.xml"));p.SetFontDefinition("NewBody","Arial",20,false,false);Check(p.FontNames.Contains("NewBody"),"New definition not selectable.");string file=Path.Combine(root,"font-definition.mp1skinproj");ProjectFile.Save(p,file);var restored=ProjectFile.Load(file);Check(restored.FontSpecs["NewBody"].Height==20&&File.ReadAllText(p.Resolve("fonts.xml"))==disk,"Font project round trip changed original disk XML.");});
            Test("Shared font edits respect locks through aliases",()=>{var p=open();p.Editor.Locked.Add(p.Controls[1].Key);Reject(()=>p.SetFontDefinition("Body","Arial",20,false,false));Check(p.Undo.Count==0,"A locked alias use was changed.");});
            Test("Empty font files can receive a definition without manual XML edits",()=>{string path=Path.Combine(root,"empty-font-definition");Directory.CreateDirectory(path);Write(path,"fonts.xml","<fonts custom='keep'/>");Write(path,"main.xml",Xml("<label>Text</label>"));var p=new SkinProject(path);p.OpenPage("main.xml");p.SetFontDefinition("Body","Arial",18,false,false);Check(p.FontSpecs.ContainsKey("Body")&&p.Source(p.Resolve("fonts.xml")).Text.Contains("custom='keep'"),"Empty fonts root lost its attributes.");});
            Test("Self-closing font properties retain unknown attributes",()=>{var p=open();var source=p.Source(p.Resolve("fonts.xml"));source.Text=source.Text.Replace("<height>12</height>","<height custom='keep'/>");source.Parse();p.OpenPage("main.xml");p.SetFontDefinition("Body","Arial",20,false,false);Check(p.Source(p.Resolve("fonts.xml")).Text.Contains("<height custom='keep'>20</height>"),"A self-closing font property lost attributes.");});
            Test("New font entries retain Windows source line endings",()=>{var p=open();var source=p.Source(p.Resolve("fonts.xml"));source.Text=source.Text.Replace("<fonts>","<fonts>\r\n");source.Parse();p.SetFontDefinition("NewFont","Arial",20,false,false);Check(!source.Text.Replace("\r\n","").Contains("\n"),"New font XML introduced mixed line endings.");});
        }
    }
}
